(() => {
  'use strict';
  const $=id=>document.getElementById(id),escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);
  const date=value=>value?new Date(typeof value==='string'&&value.length===10?value+'T12:00:00':value).toLocaleDateString('pt-BR'):'A confirmar';
  const money=value=>(value/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
  $('code').value=(new URLSearchParams(location.search).get('codigo')||'').slice(0,36);
  $('tracking-form').addEventListener('submit',async event=>{
    event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;$('message').textContent='Consultando seu pedido…';$('result').hidden=true;
    try{
      const response=await fetch('/api/tracking?code='+encodeURIComponent($('code').value.trim()),{cache:'no-store'}),data=await response.json();if(!response.ok)throw Error(data.message||'Não foi possível consultar agora.');
      const a=data.address||{},paid=data.paymentStatus==='PAID',cycleStart=data.delivery?.cycleStartedAt||data.paidAt,deliveryPaused=data.delivery&&data.delivery.status!=='active';
      const status=paid?'Pagamento confirmado':({WAITING_PAYMENT:'Aguardando pagamento',REFUNDED:'Pagamento estornado',CANCELED:'Pedido cancelado',REFUSED:'Pagamento recusado'}[data.paymentStatus]||data.paymentStatus);
      $('result').innerHTML=`<section class="card"><div class="summary"><div><span class="eyebrow">Seu pedido</span><h2>${escape(data.orderCode)}</h2></div><span class="badge ${paid?'paid':''}">${escape(status)}</span></div><p>Olá, <strong>${escape(data.customer.name)}</strong>!</p><p class="muted code">${escape(data.trackingCode)}</p><div class="grid"><div><h3>Entrega para</h3><p class="muted">${escape([a.street,a.streetNumber,a.complement,a.neighborhood].filter(Boolean).join(', '))}<br>${escape([a.city,a.state,a.zipCode].filter(Boolean).join(' · '))}</p></div><div><h3>Previsão de entrega</h3><p>${escape(deliveryPaused?'Aguardando definição da entrega':date(data.estimatedDelivery))}</p><p class="muted">${escape(data.carrier||'Transportadora a definir')}${data.carrierCode?'<br>Código da transportadora: '+escape(data.carrierCode):''}</p></div></div><h3>Itens do pedido</h3>${data.items.map(item=>`<p class="muted">${escape(item.quantity)} × ${escape(item.title)}</p>`).join('')}<p><strong>Total: ${escape(money(data.amount))}</strong></p></section><section class="card"><h2>O caminho da sua entrega</h2><ol class="timeline">${data.stages.map((stage,i)=>`<li class="${paid&&data.stage>=i+1?'done ':''}${paid&&data.stage===i+1?'current':''}"><h3>${escape(stage.title)}</h3><p>Dias ${stage.from} a ${stage.to}${data.paidAt?' · '+date(cycleStart+stage.from*86400000)+' a '+date(cycleStart+stage.to*86400000):' após o pagamento'}</p><p>${paid&&data.stage===i+1?(deliveryPaused?'Entrega interrompida — confira as opções acima':'Etapa atual'):paid&&data.stage>i+1?'Concluída':'Aguardando atualização'}</p></li>`).join('')}</ol></section><section class="card"><h2>Últimas atualizações</h2><ul class="history">${data.events.length?data.events.map(item=>`<li><time>${escape(new Date(item.occurred_at).toLocaleString('pt-BR'))}</time><p><strong>${escape(data.stages[item.stage-1]?.title||'Atualização')}</strong></p><p>${escape(item.note)}</p>${item.location?'<p class="muted">'+escape(item.location)+'</p>':''}</li>`).join(''):'<li class="muted">As atualizações aparecerão aqui após a confirmação do pagamento.</li>'}</ul></section>`;
      if(data.demo){const notice=document.createElement('p');notice.className='notice';notice.setAttribute('role','note');notice.textContent='MODO DE DEMONSTRAÇÃO — dados, pagamento e movimentações fictícios. Este código permanente não corresponde a uma compra e não altera pedidos reais. As datas do exemplo são ajustadas para permitir testar a visualização a qualquer momento.';$('result').prepend(notice);}
      $('result').hidden=false;$('message').textContent='';window.Redelivery?.render(data);await window.DeliveryMap.render({...data,events:data.events.filter(event=>!data.delivery||event.occurred_at>=data.delivery.cycleStartedAt)});
    }catch(error){$('message').textContent=error.message||'Não foi possível consultar agora.';}finally{button.disabled=false;}
  });
})();
